class Invoice < ApplicationRecord
  belongs_to :consignment
  belongs_to :customer

  # invoice_number is generated by PostgreSQL (see the migration), so it has no validation.
  # Uniqueness per consignment is guaranteed by the unique index on consignment_id;
  # Invoices::Generate (Step 8) relies on that index rather than a Rails validation.
  validates :freight_charge, :fuel_levy_amount, :total_amount,
    presence: true, numericality: { greater_than_or_equal_to: 0 }
  validates :issued_at, presence: true
end
